```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record the input this run received, under the shared key.
        aap::caps::state_rw::put("last-input", &feed_url);

        // Read the time once.
        let seconds = wasi::clocks::wall_clock::now().seconds;

        // The one permitted fetch. A transport failure is a value, not a trap:
        // it counts as zero characters fetched.
        let fetched = match aap::caps::http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        // Notify the digest channel. The contract requires `notified == true`,
        // so a refused notification must not produce an output.
        let message = format!("heartbeat: read {} at {}, fetched {} chars", feed_url, seconds, fetched);
        let notified = aap::caps::notifier::notify(&message);
        assert!(notified, "notifier refused the heartbeat notification");

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
